import { NextResponse } from "next/server";
import { db } from "@/lib/mysql";
import { jwtVerify } from "jose";

const secret = new TextEncoder().encode(process.env.JWT_SECRET!);

// ========================
// POST (Public Contact Form)
// ========================
export async function POST(req: Request) {
    try {
        const { name, email, mobile, message } = await req.json();

        await db.execute(
            `INSERT INTO contact_requests (name, email, mobile, message)
       VALUES (?, ?, ?, ?)`,
            [name, email, mobile, message || null]
        );

        return NextResponse.json({ success: true });
    } catch (error) {
        return NextResponse.json(
            { error: "Failed to submit contact" },
            { status: 500 }
        );
    }
}

// ========================
// GET (Admin Only)
// ========================
export async function GET(req: Request) {
    try {
        const cookie = req.headers.get("cookie");

        if (!cookie?.includes("admin_token=")) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const token = cookie
            .split(";")
            .find((c) => c.trim().startsWith("admin_token="))
            ?.split("=")[1];

        if (!token) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        await jwtVerify(token, secret);

        const [rows] = await db.query(
            `SELECT id, name, email, mobile, message, created_at
       FROM contact_requests
       ORDER BY created_at DESC`
        );

        return NextResponse.json(rows);
    } catch (error) {
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }
}
